function MDMobileV2Action({ className, label = "主要操作", style = "Primary" }: MDMobileV2ActionProps) {
  const isSecondary = style === "Secondary";
  return (
    <div className={className || `content-stretch flex h-[48px] items-center justify-center px-[var(--mnd-study-space-16,16px)] relative rounded-[var(--mnd-mobile-button-radius,24px)] ${isSecondary ? "bg-[var(--mnd-button-study-secondary,#fff1eb)] border border-[var(--mnd-button-study-border,#b85f50)] border-solid w-[98px]" : "bg-[var(--mnd-button-study-primary,#c84b3d)] w-[96px]"}`} id={isSecondary ? "node-56_180" : "node-56_179"}>
      {style === "Primary" && (
        <p className="[word-break:break-word] flex-[1_0_0] font-['Noto_Sans_SC:Medium'] font-medium leading-[24px] min-w-px relative text-[16px] text-[color:var(--mnd-button-study-onPrimary,#fffefc)] text-center" data-node-id="56:184">
          {label}
        </p>
      )}
      {isSecondary && (
        <p className="[word-break:break-word] flex-[1_0_0] font-['Noto_Sans_SC:Medium'] font-medium leading-[24px] min-w-px relative text-[16px] text-[color:var(--mnd-button-study-onSecondary,#9e382a)] text-center" data-node-id="56:185">
          {label}
        </p>
      )}
    </div>
  );
}

